@register.simple_tag
def icon(name, css_class="w-5 h-5"):
    path = _ICONS.get(name, "")
    return mark_safe(
        f'<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" '
        f'stroke-width="1.5" stroke="currentColor" class="{css_class}">{path}</svg>'
    )


@register.filter
def whatsapp_link(number, message=""):
    digits = "".join(ch for ch in str(number) if ch.isdigit())
    url = f"https://wa.me/{digits}"
    if message:
        from urllib.parse import quote

        url += f"?text={quote(message)}"
    return url


@register.filter
def stars(rating):
    try:
        rating = int(rating)
    except (TypeError, ValueError):
        rating = 0
    return range(rating)
